def f(inp):
    h,w=len(inp),len(inp[0])
    cnt=Counter(x for r in inp for x in r)
    bg=cnt.most_common(1)[0][0]
    # find the 3x3 tile: the largest fully-non-bg 3x3 block
    best=None
    for r in range(h-2):
        for c in range(w-2):
            blk=[inp[r+i][c+j] for i in range(3) for j in range(3)]
            if all(x!=bg for x in blk):
                if best is None or max(blk)>max(best[2]): best=(r,c,blk)
    r0,c0,tpl=best
    out=[row[:] for row in inp]
    for r in range(h):
        for c in range(w):
            if inp[r][c]!=bg:
                for i in range(3):
                    for j in range(3):
                        rr,cc=r+i-r0, c+j-c0
                        if 0<=rr<h and 0<=cc<w:
                            out[rr][cc]=tpl[i][j]
    return out

