    out=I.copy()
    mask=(I==2)
    for i in range(H):
        for j in range(W):
            if mask[i,j]:
                # enclosed if all 8 neighbors are 3
                if all(0<=a<H and 0<=b<W and I[a,b]==3 for a in range(max(0,i-1),min(H,i+2)) for b in range(max(0,j-1),min(W,j+2))) and H>0:
                    stack=[(i,j)]; seen=[[False]*W for _ in range(H)]
                    seen[i][j]=True
                    while stack:
                        a,b=stack.pop()
                        for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                            xx,yy=a+da,b+db
                            if 0<=xx<H and 0<=yy<W and not mask[xx,yy] and not seen[xx][yy]:
                                seen[xx][yy]=True; stack.append((xx,yy))
                    for a in range(H):
                        for b in range(W):
                            if seen[a][b]: out[a][b]=1
    return out.tolist()
